const { getState, getProps, itemType, relatedItemType } = options;
const { favoriteSearch } = getState();
const { favorites } = getProps();
const { label: favoriteLabel } = favorites[favoriteSearch] || {};
const { name: itemTypeName, label_plural: itemTypeLabel } = relatedItemType || itemType;
const label = favoriteLabel || itemTypeLabel || itemTypeName;
return { label };
